{
  "name": "nanomneme",
  "version": "0.9.1",
  "private": true,
  "type": "module",
  "keywords": [
    "pi-package",
    "pi-extension",
    "claude-code-plugin",
    "opencode-plugin",
    "coding-agent",
    "extension",
    "memory",
    "memory-system",
    "sqlite",
    "sqlite-fts5",
    "bm25-search",
    "adapter"
  ],
  "engines": {
    "node": ">=22.19.0"
  },
  "workspaces": [
    "packages/*",
    "adapters/*"
  ],
  "pi": {
    "extensions": [
      "./adapters/pi/extensions/index.js"
    ]
  },
  "scripts": {
    "logslines:build": "node scripts/maintenance.js logslines:build",
    "logslines:update": "node scripts/maintenance.js logslines:update",
    "codex:prepare": "node scripts/maintenance.js codex:prepare",
    "codex:update": "node scripts/maintenance.js codex:update",
    "validate": "node scripts/maintenance.js validate",
    "external:check": "node scripts/external-logslines.js check",
    "external:update": "node scripts/external-logslines.js update",
    "test": "node scripts/build-logger.js --check && node --test scripts/*.test.js shared/logger/test/*.test.js packages/*/test/*.test.js adapters/*/test/*.test.js test/*.test.js"
  },
  "overrides": {
    "@opencode-ai/plugin": {
      "zod": "4.6.7",
      "effect": {
        "toml": "5.0.1"
      }
    }
  },
  "devDependencies": {
    "@earendil-works/pi-coding-agent": ">=0.87.0",
    "ajv": "8.20.0",
    "ajv-formats": "3.0.1",
    "axe-core": "4.14.0",
    "esbuild": "0.28.2",
    "semver": "7.8.5"
  }
}

{
  "name": "@openlines/nmnm-opencode",
  "version": "0.3.1",
  "description": "OpenCode adapter for nanomneme local SQLite memory",
  "type": "module",
  "keywords": [
    "opencode",
    "plugin",
    "coding-agent",
    "memory",
    "adapter"
  ],
  "main": "./index.js",
  "exports": {
    ".": {
      "import": "./index.js"
    },
    "./server": {
      "import": "./index.js"
    },
    "./tui": {
      "import": "./tui.js"
    }
  },
  "files": [
    "index.js",
    "tui.js",
    "bin",
    "src",
    "docs/OPENCODE_ADAPTER_MANUAL.md",
    "docs/img",
    "README.md",
    "LICENSE"
  ],
  "bin": {
    "nmnm-opencode": "./bin/memory.js"
  },
  "dependencies": {
    "@opencode-ai/plugin": ">=1.18.15",
    "jsonc-parser": "3.3.1",
    "@openlines/nmnm-core": "^0.3.2"
  },
  "engines": {
    "node": ">=22.13.0"
  },
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "author": "Linel Lazatin",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/linellazatin/nanomneme.git",
    "directory": "adapters/opencode"
  }
}

